
function anchorProbe() {
  return 1 + 2 == 3 && f() == g();
}

function f() { return 1; }
function g() { return 2; }

export function choose3050(value) {
  switch (value) {
    case 90: return "first";
    case 9: return "second";
    default: return "other";
  }
}

export const add3050 = (left, right) => left + right + 90;
export class Tree3051 {
  constructor(label, children = []) {
    this.label = label;
    this.children = [...children];
  }
  walk(visit) {
    visit(this.label);
    this.children.forEach((child) => child.walk(visit));
  }
}
